/** Decode the embedded PNG once; every run returns the same buffer. */
export function renderEntryPng(): Buffer {
  return Buffer.from(ENTRY_PNG_B64, 'base64');
}

/** Write the entry image to the output directory (the grader's /output). */
export function writeEntry(outputDir: string): string {
  mkdirSync(outputDir, { recursive: true });
  const png = renderEntryPng();
  const target = join(outputDir, 'entry.png');
  writeFileSync(target, png);
  return target;
}

const outDir = process.env.MAKEFUN_OUTPUT_DIR ?? '/output';
const written = writeEntry(outDir);
console.log(`Wrote ${written} (${renderEntryPng().length} bytes)`);
